using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Text;
using Microsoft.Win32;

namespace LinkScope {
    // Desktop launchers contain only public branding and the configured origin, never credentials.
    // They are generated by the elevated installer, not by the Windows monitoring service.
    internal static class DesktopApp {
        const string Description = "LinkScope desktop application (managed by LinkScope Setup)";
        const string UrlMarker = "; LinkScope Setup managed shortcut";
        const string PolicyPath = @"SOFTWARE\Policies\Microsoft\Edge";
        const string PolicyValue = "WebAppInstallForceList";
        static readonly string IconDirectory = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "LinkScope Desktop");
        static readonly string IconPath = Path.Combine(IconDirectory, "linkscope.ico");
        static readonly string PolicyRecord = Path.Combine(Config.Root, "desktop-pwa-policy.json");
        static SecurityIdentifier Sid(WellKnownSidType t) { return new SecurityIdentifier(t, null); }
        static bool Same(string a,string b) { return String.Equals(a,b,StringComparison.OrdinalIgnoreCase); }
        static bool IsLink(string path) { return (File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0; }
        static string Browser(bool edgeOnly) {
            foreach (string root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles)}.Where(x=>!String.IsNullOrEmpty(x)).Distinct(StringComparer.OrdinalIgnoreCase)) {
                string candidate = Path.Combine(root,@"Microsoft\Edge\Application\msedge.exe");
                if(File.Exists(candidate)&&!IsLink(candidate))return candidate;
            }
            if(!edgeOnly)foreach (string root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)}.Where(x=>!String.IsNullOrEmpty(x)).Distinct(StringComparer.OrdinalIgnoreCase)) {
                string candidate = Path.Combine(root,@"Google\Chrome\Application\chrome.exe");
                if(File.Exists(candidate)&&!IsLink(candidate))return candidate;
            }
            return null;
        }
        static string Origin() {
            string origin = Config.Load().Origin();
            var uri = new Uri(origin);
            if((uri.Scheme!="https" && !(uri.Scheme=="http" && uri.IsLoopback))||!String.IsNullOrEmpty(uri.UserInfo))throw new InvalidDataException("Unsupported desktop origin.");
            return uri.GetLeftPart(UriPartial.Authority)+"/";
        }
        static void PrepareIcon() {
            var admin=Sid(WellKnownSidType.BuiltinAdministratorsSid);var system=Sid(WellKnownSidType.LocalSystemSid);
            var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);acl.SetOwner(admin);
            var inheritance=InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit;
            foreach(var sid in new[]{admin,system,Sid(WellKnownSidType.BuiltinUsersSid)})
                acl.AddAccessRule(new FileSystemAccessRule(sid,sid.Equals(admin)||sid.Equals(system)?FileSystemRights.FullControl:FileSystemRights.ReadAndExecute,inheritance,PropagationFlags.None,AccessControlType.Allow));
            var dir=Directory.CreateDirectory(IconDirectory,acl);
            if(IsLink(IconDirectory))throw new IOException("Unexpected desktop icon directory link.");
            var owner=dir.GetAccessControl().GetOwner(typeof(SecurityIdentifier));
            using(var identity=WindowsIdentity.GetCurrent())if(!owner.Equals(admin)&&!owner.Equals(system)&&!owner.Equals(identity.User))throw new UnauthorizedAccessException("Unexpected desktop icon directory owner.");
            dir.SetAccessControl(acl);
            if(File.Exists(IconPath)&&IsLink(IconPath))throw new IOException("Unexpected desktop icon link.");
            string tmp=Path.Combine(IconDirectory,Guid.NewGuid().ToString("N")+".tmp");
            try {
                byte[] bytes=Program.Resource("linkscope.ico");
                using(var file=new FileStream(tmp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(bytes,0,bytes.Length);file.Flush(true);}
                if(File.Exists(IconPath))File.Replace(tmp,IconPath,null);else File.Move(tmp,IconPath);
                var rights=new FileSecurity();rights.SetAccessRuleProtection(true,false);rights.SetOwner(admin);
                rights.AddAccessRule(new FileSystemAccessRule(admin,FileSystemRights.FullControl,AccessControlType.Allow));
                rights.AddAccessRule(new FileSystemAccessRule(system,FileSystemRights.FullControl,AccessControlType.Allow));
                rights.AddAccessRule(new FileSystemAccessRule(Sid(WellKnownSidType.BuiltinUsersSid),FileSystemRights.ReadAndExecute,AccessControlType.Allow));
                File.SetAccessControl(IconPath,rights);
            }finally{if(File.Exists(tmp))File.Delete(tmp);}
        }
        static object Invoke(object instance,string name,BindingFlags flag,params object[] args) {
            return instance.GetType().InvokeMember(name,flag,null,instance,args);
        }
        static void Release(object o){if(o!=null&&Marshal.IsComObject(o))Marshal.FinalReleaseComObject(o);}
        static bool OwnedShortcut(object shell,string path) {
            if(!File.Exists(path)||IsLink(path))return false;
            if(path.EndsWith(".url",StringComparison.OrdinalIgnoreCase)) {
                if(new FileInfo(path).Length>16384)return false;
                using(var reader=new StreamReader(path))return reader.ReadLine()==UrlMarker;
            }
            object link=null;
            try{link=Invoke(shell,"CreateShortcut",BindingFlags.InvokeMethod,path);return String.Equals(Convert.ToString(Invoke(link,"Description",BindingFlags.GetProperty)),Description,StringComparison.Ordinal);}
            finally{Release(link);}
        }
        static void Publish(object shell,string folder,string browser,string origin) {
            if(String.IsNullOrEmpty(folder)||!Directory.Exists(folder)||IsLink(folder))throw new IOException("Desktop or Start menu folder is unavailable or redirected.");
            string linkPath=Path.Combine(folder,"LinkScope.lnk"),urlPath=Path.Combine(folder,"LinkScope.url");
            string dest=browser==null?urlPath:linkPath,other=browser==null?linkPath:urlPath;
            if(File.Exists(dest)&&!OwnedShortcut(shell,dest))throw new IOException("An unmanaged shortcut already exists: "+dest);
            string tmp=Path.Combine(folder,"LinkScope-"+Guid.NewGuid().ToString("N")+(browser==null?".url":".lnk"));
            try {
                if(browser==null) {
                    using(var file=new FileStream(tmp,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var writer=new StreamWriter(file,Encoding.Unicode))
                        writer.Write(UrlMarker+"\r\n[InternetShortcut]\r\nURL="+origin+"\r\nIconFile="+IconPath+"\r\nIconIndex=0\r\n");
                } else {
                    object link=null;
                    try {
                        link=Invoke(shell,"CreateShortcut",BindingFlags.InvokeMethod,tmp);
                        Invoke(link,"TargetPath",BindingFlags.SetProperty,browser);
                        Invoke(link,"Arguments",BindingFlags.SetProperty,"--app=\""+origin+"\"");
                        Invoke(link,"WorkingDirectory",BindingFlags.SetProperty,Path.GetDirectoryName(browser));
                        Invoke(link,"IconLocation",BindingFlags.SetProperty,IconPath+",0");
                        Invoke(link,"Description",BindingFlags.SetProperty,Description);
                        Invoke(link,"Save",BindingFlags.InvokeMethod);
                    }finally{Release(link);}
                }
                if(File.Exists(dest)) {
                    if(!OwnedShortcut(shell,dest))throw new IOException("Shortcut changed during setup.");
                    File.Replace(tmp,dest,null);
                } else File.Move(tmp,dest);
                if(OwnedShortcut(shell,other))File.Delete(other);
                Console.WriteLine("Desktop web app shortcut: "+dest);
            }finally{if(File.Exists(tmp))File.Delete(tmp);}
        }
        // Migrate only known legacy product shortcut names in shared shell folders, and only
        // when their resolved target is exactly the installed service binary. Never delete an EXE.
        static void RemoveLegacyServiceLinks(object shell,string folder) {
            if(String.IsNullOrEmpty(folder)||!Directory.Exists(folder)||IsLink(folder))return;
            string expected=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"LinkScope","LinkScope.exe");
            foreach(string name in new[]{"LinkScope.lnk","LinkScope.exe.lnk","LinkScope Service.lnk","LinkScope.exe - Shortcut.lnk","LinkScope - Shortcut.lnk"}) {
                string path=Path.Combine(folder,name);if(!File.Exists(path)||IsLink(path))continue;
                object link=null;bool legacy=false;
                try {
                    link=Invoke(shell,"CreateShortcut",BindingFlags.InvokeMethod,path);
                    string target=Convert.ToString(Invoke(link,"TargetPath",BindingFlags.GetProperty));
                    if(!String.IsNullOrWhiteSpace(target)&&Path.IsPathRooted(target))legacy=Same(Path.GetFullPath(target),expected);
                } finally {Release(link);}
                if(legacy){File.Delete(path);Console.WriteLine("Removed legacy service shortcut: "+path);}
            }
        }
        static string[] ShortcutFolders() {return new[]{Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.CommonPrograms)}.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
        static object Shell() {return Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("72C24DD5-D70A-438B-8A42-98424B88AFB8")));}
        internal static void Provision(bool managedPwa) {
            string origin;try{origin=Origin();}catch(Exception ex){Console.Error.WriteLine("Desktop integration warning: "+ex.Message);return;}
            object shell=null;
            try {
                string browser=Browser(false);PrepareIcon();shell=Shell();
                string desktop=Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory);
                foreach(string folder in ShortcutFolders())try {
                    RemoveLegacyServiceLinks(shell,folder);
                    if(Same(folder,desktop)&&browser==null) {
                        // A normal URL is not an app window; keep fallback in Start only.
                        if(!String.IsNullOrEmpty(folder)&&Directory.Exists(folder)&&!IsLink(folder))foreach(string name in new[]{"LinkScope.url","LinkScope.lnk"}) {
                            string path=Path.Combine(folder,name);if(OwnedShortcut(shell,path))File.Delete(path);
                        }
                        Console.WriteLine("Desktop app shortcut skipped: supported browser unavailable. Start menu URL fallback only.");
                        continue;
                    }
                    Publish(shell,folder,browser,origin);
                } catch(Exception ex){Console.Error.WriteLine("Desktop shortcut warning: "+ex.Message);}
            }
            catch(Exception ex){Console.Error.WriteLine("Desktop integration warning: "+ex.Message);}
            finally{Release(shell);}
            if(managedPwa)try{RegisterEdge(origin);}catch(Exception ex){Console.Error.WriteLine("Managed PWA not registered: "+ex.Message);}
        }
        // Edge's documented policy installs the actual PWA the next time a compatible profile runs.
        // Never replace or merge an existing policy belonging to IT or another application.
        // A common desktop .lnk already exists, so do not ask Edge to create a second desktop icon.
        static string ReadOwnedPolicy() {return File.Exists(PolicyRecord)&&!IsLink(PolicyRecord)?Config.Json().Deserialize<string>(File.ReadAllText(PolicyRecord)):null;}
        static void RegisterEdge(string origin) {
            if(Browser(true)==null){Console.WriteLine("Managed PWA skipped: system-wide Edge is unavailable.");return;}
            using(var user=Registry.CurrentUser.OpenSubKey(PolicyPath))if(user!=null&&user.GetValue(PolicyValue)!=null){Console.WriteLine("Managed PWA skipped: current user has an existing Edge web-app policy.");return;}
            string value=Config.Json().Serialize(new[]{new {url=origin,default_launch_container="window",create_desktop_shortcut=false,custom_name="LinkScope"}});
            string owned=ReadOwnedPolicy();
            using(var hive32=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Registry32))
            using(var key32=hive32.OpenSubKey(PolicyPath))if(key32!=null&&key32.GetValue(PolicyValue)!=null&&!String.Equals(key32.GetValue(PolicyValue) as string,owned,StringComparison.Ordinal)) {
                Console.WriteLine("Managed PWA skipped: existing 32-bit Edge policy preserved.");return;
            }
            using(var hive=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Registry64))
            using(var key=hive.CreateSubKey(PolicyPath)) {
                object current=key.GetValue(PolicyValue);
                if(current!=null&&(owned==null||!String.Equals(current as string,owned,StringComparison.Ordinal))) {
                    Console.WriteLine("Managed PWA skipped: existing organization or third-party Edge policy preserved.");return;
                }
                if(current!=null&&String.Equals(current as string,value,StringComparison.Ordinal)){Console.WriteLine("LinkScope managed PWA policy already present.");return;}
                // Re-read before changing to reduce race with policy refresh. Never modify unrelated values.
                if(!Object.Equals(current,key.GetValue(PolicyValue)))throw new IOException("Edge policy changed during setup.");
                key.SetValue(PolicyValue,value,RegistryValueKind.String);
                try{Config.Save(PolicyRecord,value);}
                catch {
                    // Roll back only our just-written exact value; do not touch a changed policy.
                    if(String.Equals(key.GetValue(PolicyValue) as string,value,StringComparison.Ordinal)) {
                        if(current==null)key.DeleteValue(PolicyValue,false);else key.SetValue(PolicyValue,current,RegistryValueKind.String);
                    }
                    throw;
                }
            }
            Console.WriteLine("LinkScope Edge PWA registration policy installed; browser will apply it when a supported profile runs. Existing browser policies were not replaced.");
        }
        internal static void Remove() {
            object shell=null;try{shell=Shell();foreach(string folder in ShortcutFolders())if(!String.IsNullOrEmpty(folder)&&Directory.Exists(folder)&&!IsLink(folder))foreach(string file in new[]{"LinkScope.lnk","LinkScope.url"}){string p=Path.Combine(folder,file);if(OwnedShortcut(shell,p))File.Delete(p);}}
            catch(Exception ex){Console.Error.WriteLine("Desktop shortcut cleanup warning: "+ex.Message);}finally{Release(shell);}
            try {
                string owned=ReadOwnedPolicy();
                if(owned!=null)using(var hive=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Registry64))using(var key=hive.OpenSubKey(PolicyPath,true)) {
                    if(key!=null&&String.Equals(key.GetValue(PolicyValue) as string,owned,StringComparison.Ordinal))key.DeleteValue(PolicyValue,false);
                    File.Delete(PolicyRecord);
                }
            }catch(Exception ex){Console.Error.WriteLine("Managed PWA cleanup warning: "+ex.Message);}
            // Keep the small public icon asset so any independently installed PWA shortcuts remain valid.
        }
    }
}
